if ( ! defined( 'ABSPATH' ) ) { exit; }

$checks = array();
function riffit_check( $condition, string $label ): void {
    global $checks;
    if ( ! $condition ) { throw new RuntimeException( $label ); }
    $checks[] = $label;
}
function riffit_call( string $method, string $path, array $params = array() ): WP_REST_Response {
    $request = new WP_REST_Request( $method, '/riffit/v1' . $path );
    if ( 'GET' === $method ) { $request->set_query_params( $params ); }
    else { $request->set_body_params( $params ); }
    return rest_do_request( $request );
}
function riffit_user( int $id ): void {
    wp_set_current_user( $id );
    if ( function_exists( 'buddypress' ) ) { buddypress()->loggedin_user->id = $id; }
}

