    $account_auth = new Riffit\Auth();
    $mine_one = $account_auth->session_for_user( get_userdata( $new_user ) );
    $mine_two = $account_auth->session_for_user( get_userdata( $new_user ) );
    $other_one = $account_auth->session_for_user( get_userdata( $member ) );
    $account_request = new WP_REST_Request( 'GET', '/riffit/v1/account' );
    $account_request->set_header( 'Authorization', 'Bearer ' . $mine_one['token'] );
    $private_account = rest_do_request( $account_request );
    riffit_check( $email === $private_account->get_data()['email'] && 2 === $private_account->get_data()['sessions'], 'account response contains only the signed-in member private email and session count' );
    riffit_user( 0 );
    $others_request = new WP_REST_Request( 'DELETE', '/riffit/v1/account/sessions' );
    $others_request->set_header( 'Authorization', 'Bearer ' . $mine_one['token'] );
    riffit_check( 200 === rest_do_request( $others_request )->get_status(), 'member can revoke other sessions' );
    riffit_user( 0 );
    $account_request->set_header( 'Authorization', 'Bearer ' . $mine_two['token'] );
    riffit_check( 401 === rest_do_request( $account_request )->get_status(), 'other browser session is revoked' );
    riffit_user( 0 );
    $account_request->set_header( 'Authorization', 'Bearer ' . $mine_one['token'] );
    riffit_check( 200 === rest_do_request( $account_request )->get_status(), 'current browser stays signed in after revoking others' );
    riffit_user( 0 );
    $account_request->set_header( 'Authorization', 'Bearer ' . $other_one['token'] );
    riffit_check( 200 === rest_do_request( $account_request )->get_status(), 'revoking own sessions preserves other members sessions' );
    $admin_auth = new Riffit\Auth();
    $admin_email = $admin_auth->session_for_user( $admin );
    riffit_check( is_wp_error( $admin_email ) && 'riffit_admin_wordpress_required' === $admin_email->get_error_code(), 'site administrators cannot obtain sessions through email links' );
    $promoted_session = $admin_auth->session_for_user( get_userdata( $new_user ) );
    $promoted_request = new WP_REST_Request( 'GET', '/riffit/v1/me' );
    $promoted_request->set_header( 'Authorization', 'Bearer ' . $promoted_session['token'] );
    $promoted_user = get_userdata( $new_user ); $promoted_user->add_cap( 'manage_options' ); riffit_user( 0 );
    riffit_check( 401 === rest_do_request( $promoted_request )->get_status(), 'promotion to site administrator invalidates a prior email session' );
    $promoted_user->remove_cap( 'manage_options' );
    $admin_wordpress = $admin_auth->session_for_user( $admin, 'wordpress' );
    $admin_request = new WP_REST_Request( 'GET', '/riffit/v1/me' );
    $admin_request->set_header( 'Authorization', 'Bearer ' . $admin_wordpress['token'] ); riffit_user( 0 );
    riffit_check( 200 === rest_do_request( $admin_request )->get_status(), 'verified WordPress provider session can identify a site administrator' );
    $auth_review = new Riffit\Auth();
    $review_session = $auth_review->session_for_user( get_userdata( $new_user ) );
    $review_request = new WP_REST_Request( 'GET', '/riffit/v1/me' );
    $review_request->set_header( 'Authorization', 'Bearer ' . $review_session['token'] );
    bbp_set_user_role( $new_user, bbp_get_blocked_role() ); riffit_user( 0 );
    riffit_check( 401 === rest_do_request( $review_request )->get_status(), 'existing session rejects an account blocked after sign-in' );
    bbp_set_user_role( $new_user, bbp_get_participant_role() ); riffit_user( 0 );
    riffit_check( 401 === rest_do_request( $review_request )->get_status(), 'unblocking does not revive a revoked session' );
    $review_session = $auth_review->session_for_user( get_userdata( $new_user ) );
    $review_request->set_header( 'Authorization', 'Bearer ' . $review_session['token'] );
    wp_set_password( 'Disposable-password-for-integration-only', $new_user ); riffit_user( 0 );
    riffit_check( 401 === rest_do_request( $review_request )->get_status(), 'WordPress password changes revoke Riffit sessions' );
    $review_session = $auth_review->session_for_user( get_userdata( $new_user ) );
    $review_request->set_header( 'Authorization', 'Bearer ' . $review_session['token'] );
    wp_update_user( array( 'ID' => $new_user, 'user_pass' => 'Another-disposable-integration-password' ) ); riffit_user( 0 );
    riffit_check( 401 === rest_do_request( $review_request )->get_status(), 'WordPress profile password updates revoke Riffit sessions' );
    $review_session = $auth_review->session_for_user( get_userdata( $new_user ) );
    $review_request->set_header( 'Authorization', 'Bearer ' . $review_session['token'] );
    wp_update_user( array( 'ID' => $new_user, 'user_email' => 'changed-member@example.test' ) ); riffit_user( 0 );
    riffit_check( 401 === rest_do_request( $review_request )->get_status(), 'WordPress email changes revoke Riffit sessions' );
    for ( $i = 0; $i < 2; $i++ ) { riffit_call( 'POST', '/auth/email/request', array( 'email' => $email, 'proof' => $proof ) ); }
    $limited = riffit_call( 'POST', '/auth/email/request', array( 'email' => $email, 'proof' => $proof ) );
    riffit_check( 429 === $limited->get_status(), 'repeated email requests are limited' );
    $other_email = 'expiry@example.test';
    riffit_call( 'POST', '/auth/email/request', array( 'email' => $other_email, 'proof' => $proof ) );
    preg_match( '/code=([a-f0-9]{64})/', $mail_body, $other_matches );
    $wpdb->update( $wpdb->prefix . 'riffit_challenges', array( 'expires_at' => '2000-01-01 00:00:00' ), array( 'token_hash' => hash( 'sha256', $other_matches[1] ) ) );
    $expired = riffit_call( 'POST', '/auth/email/consume', array( 'code' => $other_matches[1], 'verifier' => $verifier ) );
    riffit_check( 401 === $expired->get_status(), 'expired email links are rejected' );
    require_once ABSPATH . 'wp-admin/includes/template.php';
    $auth = new Riffit\Auth();
    riffit_check( 'https://riffit.example.test' === $auth->sanitize_origin( 'javascript:alert(1)' ), 'unsafe frontend URL rejected' );
    riffit_check( 'https://riffit.example.test' === $auth->sanitize_origin( 'https://attacker.example/path' ), 'frontend configuration accepts an origin, not an arbitrary redirect path' );
    riffit_check( 'https://safe.example' === $auth->sanitize_origin( 'https://safe.example/' ), 'valid HTTPS frontend origin accepted' );

    file_put_contents( '/riffit-results/wordpress-results.json', wp_json_encode( array( 'passed' => true, 'count' => count( $checks ), 'checks' => $checks ), JSON_PRETTY_PRINT ) );
} catch ( Throwable $error ) {
    file_put_contents( '/riffit-results/wordpress-results.json', wp_json_encode( array( 'passed' => false, 'count' => count( $checks ), 'checks' => $checks, 'error' => $error->getMessage(), 'trace' => $error->getTraceAsString() ), JSON_PRETTY_PRINT ) );
    throw $error;
}
